css:
.resume{max-width: 210mm;
      width: 100%;
      background: #ffffff;
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08), 0 8px 20px rgba(0, 0, 0, 0.06);
      border-radius: 4px;
      overflow: hidden;
      margin: 0 auto;}
.page{width: 100%;
      background: white;
      padding: 1.2in 1in 1in 1in; 
      position: relative;
      display: flex;
      flex-direction: column;
      gap: 0.5rem;}
.divider{border: none;
      border-top: 1px solid #cbd5e0;
      margin: 0.35rem 0 0.6rem 0;
      opacity: 0.6;}
.accent-line{border: none;
      border-top: 2px solid #b68b5c; 
      width: 100%;
      margin: 0.2rem 0 0.5rem 0;}
.thin-accent{border-top: 1px solid #e2e8f0;
      margin: 0.6rem 0;}
.name-section{margin-bottom: 0.1rem;}
.name{font-size: 28pt;
      font-weight: 700;
      letter-spacing: 2px;
      color: #1a202c;
      font-family: 'Helvetica Neue', 'Arial', '思源黑体', sans-serif;
      line-height: 1.2;
      margin-bottom: 0.1rem;}
.title-sub{font-size: 12pt;
      font-weight: 400;
      color: #4a5568;
      text-transform: uppercase;
      letter-spacing: 2px;
      margin-top: 0.1rem;
      margin-bottom: 0.4rem;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
      font-size: 10pt;
      color: #2d3748;
      margin: 0.5rem 0 0.3rem 0;
      align-items: center;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;}
.contact-icon{font-weight: 400;
      color: #b68b5c;
      font-size: 11pt;
      display: inline-block;
      width: 16px;
      text-align: center;}
.section-title{font-size: 11pt;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 2.5px;
      color: #1a202c;
      margin-top: 1.1rem;
      margin-bottom: 0.15rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;}
.section-title::after{content: "";
      flex: 1;
      height: 1px;
      background: #cbd5e0;
      margin-left: 0.5rem;
      opacity: 0.7;}
.summary-text{font-size: 10.5pt;
      color: #2d3748;
      line-height: 1.6;
      margin: 0.5rem 0 0.2rem 0;}
.experience-item{margin-bottom: 0.85rem;}
.exp-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.15rem;}
.company-name{font-weight: 700;
      font-size: 11pt;
      color: #1a202c;
      letter-spacing: 0.3px;}
.job-title{font-weight: 600;
      font-size: 10.5pt;
      color: #2d3748;
      margin-left: 0.3rem;
      font-style: normal;}
.date-range{font-size: 9.5pt;
      color: #4a5568;
      font-weight: 400;
      white-space: nowrap;
      margin-left: auto;}
.bullet-list{list-style: none;
      margin-top: 0.25rem;
      padding-left: 0.15rem;}
.bullet-list li{font-size: 10pt;
      color: #2d3748;
      margin-bottom: 0.25rem;
      display: flex;
      align-items: baseline;
      gap: 0.5rem;
      line-height: 1.5;}
.bullet-list li::before{content: "•";
      color: #b68b5c;
      font-weight: 700;
      font-size: 11pt;
      display: inline-block;
      width: 14px;
      flex-shrink: 0;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 0.5rem 0.8rem;
      margin-top: 0.3rem;}
.skill-tag{font-size: 9.5pt;
      background: transparent;
      color: #2d3748;
      border: 1px solid #cbd5e0;
      padding: 0.2rem 0.8rem;
      border-radius: 2px;
      letter-spacing: 0.3px;
      background: #f7fafc;
      font-weight: 400;}
.edu-item{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.3rem;
      font-size: 10.5pt;}
.edu-degree{font-weight: 700;
      color: #1a202c;}
.edu-school{font-weight: 400;
      color: #2d3748;
      margin-left: 0.3rem;}
.edu-date{font-size: 9.5pt;
      color: #4a5568;}
.award-item{font-size: 10pt;
      margin-bottom: 0.25rem;
      display: flex;
      gap: 0.3rem;}
.award-name{font-weight: 600;
      color: #1a202c;}
.two-col-grid{display: flex;
      gap: 2rem;
      margin-top: 0.2rem;}
.col{flex: 1;
      display: flex;
      flex-direction: column;
      gap: 0.2rem;}
.skill-line{font-size: 10pt;
      display: flex;
      justify-content: space-between;
      border-bottom: 1px dotted #e2e8f0;
      padding-bottom: 0.2rem;}
.resume hr{border: 0.5px solid #e2e8f0;
      margin: 0.5rem 0;}

.resume-title{font-size:9pt;letter-spacing:0.12em;color:#b68b5c;margin-bottom:8px}.two-col-block{display:flex;gap:2rem;margin-top:0.2rem;flex-wrap:wrap}.two-col-block .col{flex:1}.misc-line{display:flex;gap:2rem;font-size:10pt;color:#2d3748;border-top:1px solid #e2e8f0;padding-top:0.6rem;margin-top:0.6rem}.misc-line strong{color:#1a202c}.lang,.cert{margin-right:8px}
